{
  "titre": "Understand supply and demand",
  "objectifGeneral": "Examine real-world cases to master supply and demand interaction",
  "notionsPivots": [
    "the law of supply",
    "the law of demand",
    "market equilibrium",
    "price elasticity",
    "consumer surplus",
    "producer surplus"
  ],
  "etapes": [
    {
      "titre": "Prepare at home: core concepts and self-check",
      "objectif": "Identify basic supply and demand principles through guided reading and verification",
      "cartes": [
        {
          "titre": "Read supply and demand definitions",
          "objectif": "Distinguish key terms related to supply and demand",
          "module": "InteractiveBook",
          "palier": "decouverte",
          "duree": 20,
          "consigne": "Read the provided definitions and examples for 'the law of supply', 'the law of demand', and 'market equilibrium'. Be ready to compare them in the next step."
        },
        {
          "titre": "Verify understanding with a quiz",
          "objectif": "Check the comprehension of supply and demand fundamentals",
          "module": "SingleChoiceSet",
          "palier": "decouverte",
          "duree": 15,
          "consigne": "Complete the single-choice questions on supply, demand and equilibrium. Use this quiz to identify any gaps before the in-class case study."
        }
      ]
    },
    {
      "titre": "Solve together: apply concepts to a case study",
      "objectif": "Analyze a real-world situation using supply and demand analysis",
      "cartes": [
        {
          "titre": "Work on the supply and demand case study",
          "objectif": "Apply supply and demand principles to evaluate market changes",
          "module": "Devoir",
          "palier": "transfert",
          "duree": 25,
          "consigne": "In class, work in small groups to solve the provided case study. Use graphs and data to support your analysis of shifts in supply, demand, and equilibrium."
        }
      ]
    },
    {
      "titre": "Review and assess",
      "objectif": "Evaluate your learning and correct misconceptions",
      "cartes": [
        {
          "titre": "Complete self-assessment quiz",
          "objectif": "Assess your mastery of supply and demand concepts",
          "module": "test_elea",
          "palier": "entrainement",
          "duree": 10,
          "consigne": "Answer the questions about supply, demand and equilibrium based on your class work and the case study. Use this quiz to confirm your understanding and get immediate feedback."
        }
      ]
    }
  ]
}
